 75→// 검색 결과 캐싱용 래디스 초기화
 76→func SearchCacheRedisInitHandler() {
 77→	defer LogForPanic()
 78→
 79→	if config.IsUsingRedis() {
 80→		if redisClusterInfo := config.GetSearchCacheRedisClusterInfo(); len(redisClusterInfo) > 0 {
 81→
 82→			searchClient = redis.NewClusterClient(&redis.ClusterOptions{
 83→				Addrs:        redisClusterInfo,
 84→				Password:     "ekskdhk1!", // no password set
 85→				MinIdleConns: 3,
 86→				PoolSize:     200,
 87→				PoolTimeout:  time.Second * 2,
 88→				IdleTimeout:  time.Second * 2,
 89→			})
 90→
 91→			res := searchClient.Ping(context.TODO())
 92→			if res.Err() != nil {
 93→				logger.Error("Redis Cluster Connection Fail...", res.Err())
 94→			} else {
 95→				logger.Info("Redis Cluster Connection Success...")
 96→			}
 97→		}
 98→	} else {
 99→		logger.Info("Redis Cluster Disconnected..")
100→	}
101→}
