240→// SetSearchCache - 검색엔진 결과를 래디스에 저장
241→func SetSearchCache(key string, result response.Result, ttl time.Duration) {
242→	defer LogForPanic()
243→
244→	if config.IsUsingRedis() {
245→		if resultStr, err := json.Marshal(result); err != nil {
246→			fmt.Println("cached fail: ", err)
247→		} else if ttl > 0 {
248→			StatusCmd := searchClient.Set(context.TODO(), key, resultStr, ttl)
249→			if StatusCmd.Err() != nil {
250→				fmt.Println("Set Cache", StatusCmd.String())
251→				logger.Error("Set Cache Error", StatusCmd.Err())
252→			}
253→		} else {
254→			logger.Error("TTL zero ttl: ", ttl)
255→		}
256→	}
257→
258→	return
259→}
