261→// 래디스에 검색 결과 조회
262→func GetSearchCache(key string) (result response.Result, err error) {
263→	defer LogForPanic()
264→
265→	if config.IsUsingRedis() {
266→		resultStr := searchClient.Get(context.TODO(), key).Val()
267→		err = json.Unmarshal([]byte(resultStr), &result)
268→	}
269→
270→	return
271→}
