107→엘라스틱서치 시드 정보를 변경
108→target: search 또는 office
109→seeds: 엘라스틱서치 주소 (ex: http://127.0.0.1:9200)
110→*/
111→func SetElasticURI(target string, seeds []string) (message string, result bool) {
112→	if len(seeds) == 0 {
113→		message = "시드는 필수 입니다."
114→		result = false
115→		return
116→	} else if !(strings.ToLower(target) == "search" || strings.ToLower(target) == "office") {
117→		message = "대상은 search, office 가능합니다."
118→		result = false
119→		return
120→	} else if strings.ToLower(target) == "search" {
121→		//	SEARCH_ELASTIC_SEED
122→		if !isSeedDiff(ElasticSeedMap["SEARCH_ELASTIC_SEED"], seeds) {
123→			message = "기존 시드정보와 동일 합니다."
124→			result = false
125→			return
126→		}
127→		ElasticSeedMap["SEARCH_ELASTIC_SEED"] = seeds
128→		message = "통합검색 엘라스틱서치 시드를 정상적으로 변경하였습니다."
129→	} else if strings.ToLower(target) == "office" {
130→		//	OFFICE_ELASTIC_SEED
131→		if !isSeedDiff(ElasticSeedMap["OFFICE_ELASTIC_SEED"], seeds) {
132→			message = "기존 시드정보와 동일 합니다."
133→			result = false
134→			return
135→		}
136→		ElasticSeedMap["OFFICE_ELASTIC_SEED"] = seeds
137→		message = "오피스 엘라스틱서치 시드를 정상적으로 변경하였습니다."
138→	} /*else {
139→		if !isSeedDiff(ElasticSeedMap["SEARCH_ANALYZER_SEED"], seeds) {
140→			message = "기존 시드정보와 동일 합니다."
141→			result = false
142→			return
143→		}
144→		ElasticSeedMap["SEARCH_ANALYZER_SEED"] = seeds
145→		message = "형태소 분석기 엘라스틱서치 시드를 정상적으로 변경하였습니다."
146→	}*/
147→	if !saveElasticSeedFile() {
148→		fmt.Println("파일 저장 실패")
149→	}
150→
151→	result = true
152→	return
153→}
