186→func saveElasticSeedFile() bool {
187→	elasticSeedJsonPath := path.Join(getConfigPath(), ELASTIC_SEED_JSON_FILE)
188→	f, err := os.Create(elasticSeedJsonPath)
189→	if err != nil {
190→		return false
191→	}
192→	defer f.Close()
193→	b, err := json.Marshal(ElasticSeedMap)
194→	if err != nil {
195→		return false
196→	}
197→	f.Write(b)
198→	f.Sync()
199→	return true
200→}
