func GetProductImageURLOriginal(productCode string) (imageURL string) {

	//code := strconv.Itoa(productCode)
	code, _ := strconv.Atoi(productCode)

	if code > 0 {
		if code > 500000 {
			subImagePath1 := productCode[len(productCode)-3 : len(productCode)]
			subImagePath2 := productCode[len(productCode)-6 : len(productCode)-3]
			imageURL = "http://img.danawa.com/prod_img/500000/" + subImagePath1 + "/" + subImagePath2 + "/img/" + productCode + "_1.jpg"
		} else {

			imageURL = "http://img.danawa.com/prod_img/large/group_" + fmt.Sprintf("%.0f", math.Floor(float64(code)/500)) + "/" + productCode + "_1.jpg"
		}
	}

	return
}

func GetDanawaPCImageURLOriginal(shopProductCode string) (imageURL string) {

	//code := strconv.Itoa(productCode)
	code, _ := strconv.Atoi(shopProductCode)

	if code > 0 {
		subImagePath1 := shopProductCode[len(shopProductCode)-3 : len(shopProductCode)]
		subImagePath2 := shopProductCode[len(shopProductCode)-6 : len(shopProductCode)-3]
		switch config.GetEnv() {
		case "DEVELOPER_PC", "DEVELOPING_SERVER":
			imageURL = "http://img.danawa.com/prod_img/pcshop_test/img/"

		case "OPERATING_SERVER":
			imageURL = "http://img.danawa.com/prod_img/pcshop/img/"

		default:
			imageURL = "http://img.danawa.com/prod_img/pcshop/img/"
		}

		imageURL = imageURL + subImagePath1 + "/" + subImagePath2 + "/img/" + shopProductCode + "_1.jpg"
	}

	return
}

