var (
	adultCahce *gocahce.Cache
	logger     = utils.Logger
)

//GetAdultCache 성인키워드 가져오기
func GetAdultCache() *gocahce.Cache {
	if adultCahce == nil {
		SetAdultCache()
	}

	return adultCahce
}

//SetAdultCache 로컬캐시 캐시저장
func SetAdultCache() *gocahce.Cache {
	adultForm := make(map[string]gocahce.Item)

	adultList := getAdultKeyword()
	item := gocahce.Item{}
	for idx := 0; idx < len(adultList); idx++ {
		item.Object = adultList[idx]
		item.Expiration = -1

		adultForm[adultList[idx]] = item
	}

	adultCahce = gocahce.NewFrom(gocahce.NoExpiration, gocahce.DefaultExpiration, adultForm)

	return adultCahce
}

func getAdultKeyword() (adultList []string) {

	file, err := os.Open(config.GetAdultKeywordFilePath())

	if err != nil {
		logger.Error(err.Error())
	} else {
		adultList = make([]string, 0)

		defer file.Close()

		scanner := bufio.NewScanner(file)
		for scanner.Scan() {
			adultList = append(adultList, scanner.Text())
		}
	}

	return
}

