396→				if strings.Compare(string(innerItem.PRODUCTMAKER), "예랑") == 0 && strings.Compare(string(innerItem.PRODTYPE), "3") == 0 {
397→					innerItem.PRODUCTMAKER = ""
398→				}
399→
400→				if innerItem.PRODTYPE == "1" {
401→					innerItem.PRODUCTIMAGEURL = utils.GetProductImageURLOriginal(string(innerItem.PRODUCTCODE))
402→				}
403→
404→				if innerItem.PRODTYPE == "4" {
405→					innerItem.PRODUCTIMAGEURL = utils.GetDanawaPCImageURLOriginal(innerItem.SHOPPRODUCTCODE)
406→				}
407→
408→				inner = append(inner, *innerItem)
409→			}
410→
411→			if len(inner) > 1 {
412→				rankingViewer.BundleCount = (element.InnerHits["_bundle"].Hits.TotalHits.Value)
413→				rankingViewer.BundleProduct = inner
414→			} else {
415→				empty := make([]model.BundleProductEs, 0)
416→				rankingViewer.BundleCount = 0
417→				rankingViewer.BundleProduct = empty
418→			}
419→
420→			// ES 카테고리 부스팅 관련 내용(Explain)
421→			for _, item := range element.Explanation.Details {
422→				GetExplainEs(item.Details, &explainList)
423→			}
424→
425→			if len(explainList) > 0 {
426→				rankingViewer.Explain = explainList
427→			} else {
428→				empty := make([]model.Explain, 0)
429→				rankingViewer.Explain = empty

430→				sortParam, _ := fieldSorts[i].Source()
431→				sort, _ := json.Marshal(sortParam)
432→				sortSlice = append(sortSlice, string(sort))
433→			}
434→			mSort = "\"sort\" : [" + strings.Join(sortSlice, ",") + "]"
435→		}
436→
437→		utils.WriteEsQueryDebugLog(index, strconv.Itoa(from), strconv.Itoa(size), mQuery, mFsc, mHighlight, mSort, mAggs, mCollapse)
438→	}
439→
440→	res, err := esSearch.Do(context.Background()) // execute
441→	if err == nil {
442→		resultSlice := make([]interface{}, 0)
443→
444→		for _, element := range res.Hits.Hits {
445→			listES := &model.EstimateProductES{}
446→			json.Unmarshal([]byte(element.Source), &listES)
447→			if len(listES.ProductCode) > 0 {
