449→				listES.ImageURL = imageURL
450→				listES.ProductImg = imageURL + "?shrink=160:160"
451→			}
452→			list := &model.EstimateProduct{}
453→			mapstructure.Decode(listES, &list)
454→			resultSlice = append(resultSlice, list)
455→		}
456→
457→		result.Keyword = data["keyword"]
458→		result.Time = utils.GetEsSearchtimeFormat(res.TookInMillis)
459→		result.Count = len(resultSlice)
460→		result.Total_count = int(res.Hits.TotalHits.Value)
461→		result.SearchList = resultSlice
462→	} else {
463→		logger.Error(err.Error())
464→	}
465→
466→	return
467→}
