215→	b2 := base64.StdEncoding.EncodeToString([]byte(query["keyword"]))
216→	suffixKey := ""
217→	if len(b2) > 20 {
218→		suffixKey = b2[:20]
219→	} else {
220→		suffixKey = b2
221→	}
222→
223→	key = fmt.Sprintf("category:%x:%s", h1.Sum(nil), suffixKey)
224→
225→	return
226→}
