273→// ConvertAutoCompleteQueryToRedisKey - 자동완성 레디스 키
274→func ConvertAutoCompleteQueryToRedisKey(query map[string]string) (key string) {
275→	valueKey := make([]string, 0)
276→	for i := 0; i < len(autoCompleteQueryFields); i++ {
277→		valueKey = append(valueKey, query[autoCompleteQueryFields[i]]) // service, keyword
278→	}
279→
280→	joinValueKey := strings.Join(valueKey, ":")
281→
282→	h1 := sha1.New()
283→	h1.Write([]byte(joinValueKey))
284→
285→	key = fmt.Sprintf("autoComplete:%x", h1.Sum(nil))
286→
287→	return
288→}
